===== README.md =====
# ledgerline

Nightly jobs that export ledger entries to the reporting warehouse and import adjustments
back. Configuration is loaded by `src/config/load.js`.
===== package.json =====
{
  "name": "ledgerline-fixture",
  "version": "1.0.0",
  "private": true,
  "description": "Nightly ledger export and import jobs",
  "main": "src/jobs/export.js",
  "type": "commonjs"
}
===== config/staging.json =====
{
  "export": {
    "retryLimit": 5,
    "timeoutMs": 20000
  }
}
===== config/production.json =====
{
  "export": {
    "timeoutMs": 30000
  }
}
===== src/config/limits.js =====
'use strict';

// Production caps agreed with the warehouse team. They apply after every override.
module.exports = {
  production: {
    maxExportRetries: 2,
  },
};
===== src/config/load.js =====
'use strict';

const fs = require('fs');
const path = require('path');
const defaults = require('./defaults');
const limits = require('./limits');

function readEnvironmentFile(envName) {
  const file = path.join(__dirname, '..', '..', 'config', `${envName}.json`);
  if (!fs.existsSync(file)) return {};
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function fromVariables(env) {
  const out = { export: {} };
  if (env.LEDGER_EXPORT_RETRIES) out.export.retryLimit = Number(env.LEDGER_EXPORT_RETRIES);
  if (env.LEDGER_EXPORT_TIMEOUT_MS) out.export.timeoutMs = Number(env.LEDGER_EXPORT_TIMEOUT_MS);
  return out;
}

function merge(...layers) {
  const result = { export: {}, import: {} };
  for (const layer of layers) {
    Object.assign(result.export, layer.export);
    Object.assign(result.import, layer.import);
  }
  return result;
}

function load(env = process.env) {
  const envName = env.NODE_ENV || 'development';
  const config = merge(defaults, readEnvironmentFile(envName), fromVariables(env));
  const caps = limits[envName];
  if (caps) {
    config.export.retryLimit = Math.min(config.export.retryLimit, caps.maxExportRetries);
  }
  return config;
}

module.exports = { load };
===== src/config/defaults.js =====
'use strict';

module.exports = {
  export: {
    retryLimit: 3,
    timeoutMs: 10000,
  },
  import: {
    timeoutMs: 15000,
  },
};
===== src/jobs/export.js =====
'use strict';

const { load } = require('../config/load');

async function withRetries(fn, { retryLimit, timeoutMs }) {
  let lastError;
  for (let attempt = 0; attempt <= retryLimit; attempt += 1) {
    try {
      return await fn({ timeoutMs });
    } catch (error) {
      lastError = error;
    }
  }
  throw lastError;
}

async function runExport(sendBatch) {
  const config = load();
  return withRetries(sendBatch, {
    retryLimit: config.export.retryLimit,
    timeoutMs: config.export.timeoutMs,
  });
}

module.exports = { runExport, withRetries };
===== src/jobs/import.js =====
'use strict';

const { load } = require('../config/load');
const { withRetries } = require('./export');

async function runImport(fetchAdjustments) {
  const config = load();
  return withRetries(fetchAdjustments, {
    retryLimit: 5,
    timeoutMs: config.import.timeoutMs,
  });
}

module.exports = { runImport };

